"use client";

import "./label.css";
import type React from "react";
import { cn } from "@/lib/cn";

import { labelVariants, type LabelVariants } from "./label.variants";

export type LabelProps = LabelVariants & React.LabelHTMLAttributes<HTMLLabelElement>;

export const LabelRoot = ({ className, size, ...props }: LabelProps) => {
  const slots = labelVariants({ size });

  return <label className={cn(slots.root(), className)} {...props} />;
};

export const Label = LabelRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const labelVariants = tv({
  slots: {
    root: "label",
  },
  variants: {
    size: {
      sm: {
        root: "label--sm",
      },
      md: {
        root: "label--md",
      },
      lg: {
        root: "label--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type LabelVariants = VariantProps<typeof labelVariants>;

.label {
  @apply text-foreground flex items-center text-sm font-medium leading-none select-none peer-disabled:cursor-not-allowed peer-disabled:opacity-50 group-data-disabled:cursor-not-allowed group-data-disabled:opacity-50 aria-disabled:cursor-not-allowed aria-disabled:opacity-50;
}

.label--sm {
  @apply text-xs;
}

.label--md {
  @apply text-sm;
}

.label--lg {
  @apply text-base;
}

import { Label as LabelRootComponent, LabelRoot } from "./label";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/label/content.md
 */
export const Label = Object.assign(LabelRootComponent, {
  Root: LabelRoot,
});

export { LabelRoot };
export type { LabelProps } from "./label";
export { type LabelVariants, labelVariants } from "./label.variants";
